        const trigger = app.querySelector("[data-open-dialog]");
        const closeButton = app.querySelector("[data-close-dialog]");
        const confirmButton = app.querySelector("[data-confirm-delete]");
        const liveStatus = app.querySelector("#live-status");

        if (trigger) {
          trigger.addEventListener("click", () => {
            lastTrigger = trigger;
            dialog.showModal();
          });
