   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <main class="page" id="main-content">
       <div id="app"></div>
     </main>

     <script>
       const state = {
         imageDeleted: false
       };

       const imageSource =
         "data:image/svg+xml;utf8," +
         encodeURIComponent(`
           <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 900">
             <defs>
               <linearGradient id="sky" x1="0%" y1="0%" x2="100%" y2="100%">
                 <stop offset="0%" stop-color="#6c8bff" />
                 <stop offset="100%" stop-color="#18284f" />
               </linearGradient>
               <linearGradient id="hill" x1="0%" y1="0%" x2="100%" y2="100%">
                 <stop offset="0%" stop-color="#7ce0d3" />
                 <stop offset="100%" stop-color="#15353f" />
               </linearGradient>
             </defs>
             <rect width="1200" height="900" fill="url(#sky)" />
             <circle cx="925" cy="180" r="92" fill="#f7f0c0" opacity="0.9" />
             <path d="M0 660 C180 580 320 520 520 580 S900 720 1200 570 V900 H0 Z" fill="url(#hill)" />
             <path d="M0 730 C220 660 430 650 680 730 S1020 780 1200 700 V900 H0 Z" fill="#0f1d31" />
             <path d="M700 560 L785 360 L870 560 Z" fill="#f5f7ff" opacity="0.92" />
             <rect x="742" y="560" width="86" height="148" rx="10" fill="#d9e4ff" opacity="0.95" />
           </svg>
         `);

       let lastTrigger = null;

       function ImagePreview(props) {
         if (props.imageDeleted) {
           return `
             <section class="card empty-state" aria-labelledby="library-status-title">
               <div class="empty-icon" aria-hidden="true">✓</div>
               <h1 id="library-status-title">Image removed</h1>
               <p class="status" id="status-message" role="status" aria-live="polite">
                 The image has been deleted from your library.
               </p>
             </section>
           `;
         }

         return `
           <section class="card preview-layout" aria-labelledby="image-preview-title">
             <div class="image-panel">
               <figure class="image-frame">
                 <img
                   src="${imageSource}"
                   alt="Mountain peaks at dusk reflected in a calm lake"
                   width="1200"
                   height="900"
                 />
               </figure>
             </div>
             <div class="details-panel">
               <p class="eyebrow">Image preview</p>
               <h1 id="image-preview-title">Evening Light</h1>
               <p class="description">
                 A high-resolution landscape photo stored in your personal library.
               </p>
               <p class="meta" aria-label="Image details">
                 <span>4000 x 3000</span>
                 <span>PNG</span>
                 <span>4.8 MB</span>
               </p>
               <div class="actions">
                 <button type="button" class="trigger danger" data-open-dialog>
                   Delete image
                 </button>
                 <button type="button" class="secondary">Download</button>
               </div>
             </div>
           </section>
         `;
       }

       function ConfirmDeleteDialog() {
         return `
           <dialog aria-labelledby="dialog-title" aria-describedby="dialog-description">
             <div class="dialog-body">
               <p class="eyebrow">Confirm action</p>
               <h2 class="dialog-title" id="dialog-title">Delete this image?</h2>
               <p class="dialog-copy" id="dialog-description">
                 This will permanently remove <strong>Evening Light</strong> from your library.
               </p>
               <div class="dialog-actions">
                 <button type="button" class="secondary" data-close-dialog autofocus>
                   Cancel
                 </button>
                 <button type="button" class="danger" data-confirm-delete>
                   Delete from library
                 </button>
               </div>
             </div>
           </dialog>
         `;
       }

       function App() {
         return `
           <div class="shell">
             ${ImagePreview(state)}
             ${ConfirmDeleteDialog()}
           </div>
         `;
       }

       function bindEvents() {
         const app = document.getElementById("app");
         const dialog = app.querySelector("dialog");
         const trigger = app.querySelector("[data-open-dialog]");
         const closeButton = app.querySelector("[data-close-dialog]");
         const confirmButton = app.querySelector("[data-confirm-delete]");

         if (trigger) {
           trigger.addEventListener("click", () => {
             lastTrigger = trigger;
             dialog.showModal();
           });
         }

         if (closeButton) {
           closeButton.addEventListener("click", () => dialog.close("cancel"));
         }

         dialog.addEventListener("click", (event) => {
           const bounds = dialog.getBoundingClientRect();
           const isBackdropClick =
             event.clientX < bounds.left ||
             event.clientX > bounds.right ||
             event.clientY < bounds.top ||
             event.clientY > bounds.bottom;

           if (isBackdropClick) {
             dialog.close("cancel");
           }
         });

         dialog.addEventListener("close", () => {
           if (dialog.returnValue !== "deleted" && lastTrigger) {
             lastTrigger.focus();
           }
         });

         if (confirmButton) {
           confirmButton.addEventListener("click", () => {
             state.imageDeleted = true;
             dialog.close("deleted");
             render();
             const statusNode = document.getElementById("status-message");

             if (statusNode) {
               statusNode.setAttribute("tabindex", "-1");
               statusNode.focus();
             }
           });
         }
       }

       function render() {
         const app = document.getElementById("app");
         app.innerHTML = App();
         bindEvents();
       }

       render();
     </script>
')
